-- demo-33: "Scrisori cu timbru din clasa a patra" by teacher
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-003300000000'::uuid, '00000000-0000-4000-8000-000000000007'::uuid, 'scrisori-cu-timbru-din-clasa-a-patra-demo-33',
  $demo$Scrisori cu timbru din clasa a patra$demo$, $demo$Când un mesaj ajunge în mai puțin de o secundă, ce rost mai are o scrisoare care face unsprezece zile până la destinatar? O profesoară și elevii ei de clasa a patra încearcă să afle, scriind de mână unor copii dintr-un sat pe care nu l-au văzut niciodată. Un eseu în trei părți despre răbdare, greșeli de ortografie, timbre lipite strâmb și prietenii care încap într-un plic.$demo$, 'ro',
  (select id from public.categories where slug = 'nonfiction_essays'),
  'drawn', 'grid', 'paper', 'plum', 'all_ages', 'no_ai',
  now() - interval '52 days', now() - interval '46 days', now() - interval '54 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-003300000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-003300000000'::uuid, '00000000-0000-4000-8000-000000000007'::uuid, array['scrisori', 'copii', 'școală', 'prietenie', 'eseu']);
update public.stories
set cover_kind = 'drawn', cover_design = 'grid', cover_background = 'paper', cover_accent = 'plum'
where stories.id = '00000000-0000-4000-9100-003300000000'::uuid
  and (cover_kind, cover_design, cover_background, cover_accent)
    is distinct from ('drawn', 'grid', 'paper', 'plum');
