-- demo-34: "Umbrela galbenă a lui Sami" by teacher
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-003400000000'::uuid, '00000000-0000-4000-8000-000000000007'::uuid, 'umbrela-galbena-a-lui-sami-demo-34',
  $demo$Umbrela galbenă a lui Sami$demo$, $demo$Bunica Lela îi dă lui Sami o umbrelă galbenă din pod, veche și frumoasă. Are o singură problemă: nu se deschide, oricât ai trage de ea, nici măcar când toarnă cu găleata. Până într-o după-amiază în care Sami vede, sub castanul din fața blocului, o fată nouă care plânge. O poveste despre ploaie, vecini și lucrurile care se deschid doar când sunt împărțite, pentru cititori de la șase ani în sus.$demo$, 'ro',
  (select id from public.categories where slug = 'fiction'),
  'automatic', null, null, null, 'all_ages', 'no_ai',
  now() - interval '89 days', now() - interval '83 days', now() - interval '91 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-003400000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-003400000000'::uuid, '00000000-0000-4000-8000-000000000007'::uuid, array['copii', 'prietenie', 'ploaie', 'bunici', 'vecini']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-003400010000'::uuid, '00000000-0000-4000-9100-003400000000'::uuid, '00000000-0000-4000-8000-000000000007'::uuid,
  'd034c001', 1, $demo$Capitolul 1: Umbrela din pod$demo$, public.check_chapter_text($demo$În podul bunicii Lela erau multe lucruri, și toate aveau o poveste. Era un fier de călcat care se încălzea cu cărbuni, era o valiză cu abțibilduri din orașe cu nume caraghioase și era o pălărie cu o pană care, spunea bunica, fusese cândva a unui papagal foarte îngâmfat. Sami avea șase ani și jumătate și urca în pod cu bunica în fiecare sâmbătă, ca să mai afle câte o poveste.

În sâmbăta aceea, în spatele valizei, a găsit o umbrelă. Era galbenă ca o lămâie, cu mânerul de lemn sculptat în formă de cap de rață și cu un nasture de sidef care o ținea strânsă.

— Pot s-o iau? a întrebat Sami.

Bunica a zâmbit cu un colț al gurii, cum zâmbea când știa ceva ce el nu știa încă.

— Poți. Dar să știi că e o umbrelă cu toane.

Sami n-a întrebat ce înseamnă „cu toane”, pentru că era prea ocupat să desfacă nasturele. Apoi a tras de umbrelă. Nimic. A apăsat pe butonul de lângă mâner. Nimic. A scuturat-o, a întors-o cu vârful în sus, a rugat-o frumos și, la sfârșit, a amenințat-o că o lasă în pod. Umbrela a rămas strânsă, galbenă și liniștită, ca o banană foarte serioasă.

— E stricată, a zis Sami, dezamăgit.

— Nu e stricată, a zis bunica. Așteaptă.

— Ce așteaptă?

— Asta o s-o afli singur.

Luni a plouat. Nu o ploaie mică, din aceea care doar te gâdilă pe nas, ci una mare, care făcea bălți cât niște lacuri pe trotuar. Sami a luat umbrela galbenă la școală, sperând că poate, pe ploaie adevărată, se va răzgândi. La poarta școlii a încercat din nou. A tras, a apăsat, a scuturat. Colegii lui deschiseseră deja umbrele albastre, roșii și una cu dinozauri, și se uitau la el.

— Ce ai acolo? a râs Ruxi, colega lui de bancă. O umbrelă care nu face umbră?

Sami a ajuns în clasă ud până la șosete, cu umbrela strânsă sub braț, uscată de tot. Era singurul lucru uscat din el. Doamna învățătoare i-a dat un prosop și n-a zis nimic, dar Sami a văzut că se uita lung la capul de rață, ca și cum l-ar fi recunoscut.

Seara, a pus umbrela în cuier și s-a uitat urât la ea. Umbrela, desigur, nu s-a uitat urât înapoi. Umbrelele nu fac așa ceva. Dar lui Sami i s-a părut că rața de pe mâner are un fel de răbdare în ochi.$demo$), 1,
  now() - interval '89 days', $demo$Capitolul 1: Umbrela din pod$demo$, public.check_chapter_text($demo$În podul bunicii Lela erau multe lucruri, și toate aveau o poveste. Era un fier de călcat care se încălzea cu cărbuni, era o valiză cu abțibilduri din orașe cu nume caraghioase și era o pălărie cu o pană care, spunea bunica, fusese cândva a unui papagal foarte îngâmfat. Sami avea șase ani și jumătate și urca în pod cu bunica în fiecare sâmbătă, ca să mai afle câte o poveste.

