-- classic-04-fata-babei-si-fata-mosneagului: "Fata babei și fata moșneagului" by clasice
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9300-000400000000'::uuid, '00000000-0000-4000-8000-000000000100'::uuid, 'fata-babei-si-fata-mosneagului-classic',
  $demo$Fata babei și fata moșneagului$demo$, $demo$Fata moșneagului, harnică și bună, pleacă în lume și e răsplătită pentru fiecare faptă bună de pe drum. Fata babei, leneșă și rea, pleacă pe același drum. Basmul despre ce aduci acasă.

Ediția sursă: 1877. Text: Wikisource, https://ro.wikisource.org/w/index.php?oldid=134787, CC BY-SA 4.0; formatare adaptată.$demo$, 'ro',
  (select id from public.categories where slug = 'fiction'),
  'drawn', 'waves', 'blush', 'plum', 'all_ages', 'no_ai',
  now() - interval '59 days', now() - interval '59 days', now() - interval '61 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9300-000400000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9300-000400000000'::uuid, '00000000-0000-4000-8000-000000000100'::uuid, array['domeniu public', 'clasic', 'basm', 'creangă']);
